mapper.insert:
INSERT INTO t_ai_task(
    record_type, skill_code, skill_name, skill_version, input_schema, output_schema,
    risk_level, lifecycle_status, created_by
) VALUES (
    'SKILL_DEF', #{row.skillCode}, #{row.skillName}, #{row.skillVersion},
    CAST(#{row.inputSchema} AS JSON), CAST(#{row.outputSchema} AS JSON),
    #{row.riskLevel}, 'DRAFT', #{row.createdBy}
)

mapper.select:
SELECT 
FROM t_ai_task
WHERE record_type = 'SKILL_DEF'
  AND skill_code = #{skill}
  AND skill_version = #{version}
  AND lifecycle_status IN ('PUBLISHED', 'RETIRED')

SELECT 
FROM t_ai_task
WHERE record_type = 'PROMPT_VERSION'
  AND skill_code = #{skill}
  AND prompt_version = #{version}
  AND lifecycle_status IN ('PUBLISHED', 'RETIRED')

mapper.update:
UPDATE t_ai_task
SET content_sha256 = #{sha}
WHERE id = #{id}
  AND record_type = 'PROMPT_VERSION'
